package mz.co.aprendaacodar.course.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.user.entity.User;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="courses") public class Course extends BaseEntity {
 @Column(nullable=false,length=180) private String title;@Column(nullable=false,unique=true,length=200) private String slug;@Column(nullable=false,length=500) private String shortDescription;@Column(nullable=false,columnDefinition="TEXT") private String description;private String coverImageKey;@Column(nullable=false,precision=12,scale=2) private BigDecimal price;@Column(nullable=false,length=3) private String currency="MZN";private Integer durationHours;@Column(columnDefinition="TEXT") private String prerequisites;@Column(columnDefinition="TEXT") private String learningOutcomes;
 @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private CurriculumMode curriculumMode;@Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private CourseStatus status;@ManyToOne(fetch=FetchType.LAZY,optional=false) private User teacher;private Instant submittedAt;private Instant reviewedAt;@ManyToOne(fetch=FetchType.LAZY) private User reviewedBy;@Column(columnDefinition="TEXT") private String rejectionReason;private Instant publishedAt;
 protected Course(){}
 public Course(String title,String shortDescription,String description,String coverImageKey,BigDecimal price,Integer durationHours,String prerequisites,String outcomes,CurriculumMode mode,User teacher){this.title=title;this.slug=slugify(title);this.shortDescription=shortDescription;this.description=description;this.coverImageKey=coverImageKey;this.price=price;this.durationHours=durationHours;this.prerequisites=prerequisites;this.learningOutcomes=outcomes;this.curriculumMode=mode;this.teacher=teacher;this.status=CourseStatus.DRAFT;this.currency="MZN";}
 public static String slugify(String s){String x=java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("^-|-$","");return x.isBlank()?"curso":x;}
 public void update(String title,String shortDescription,String description,String coverImageKey,BigDecimal price,Integer durationHours,String prerequisites,String outcomes,CurriculumMode mode){this.title=title;this.slug=slugify(title);this.shortDescription=shortDescription;this.description=description;this.coverImageKey=coverImageKey;this.price=price;this.durationHours=durationHours;this.prerequisites=prerequisites;this.learningOutcomes=outcomes;this.curriculumMode=mode;if(status==CourseStatus.PUBLISHED)status=CourseStatus.PENDING_APPROVAL;}
 public void submit(){status=CourseStatus.PENDING_APPROVAL;submittedAt=Instant.now();}
 public void approve(User admin){status=CourseStatus.PUBLISHED;reviewedBy=admin;reviewedAt=Instant.now();publishedAt=Instant.now();rejectionReason=null;}
 public void reject(User admin,String reason){status=CourseStatus.REJECTED;reviewedBy=admin;reviewedAt=Instant.now();rejectionReason=reason;}
 public void archive(){status=CourseStatus.ARCHIVED;}
 public String getTitle(){return title;}public String getSlug(){return slug;}public String getShortDescription(){return shortDescription;}public String getDescription(){return description;}public String getCoverImageKey(){return coverImageKey;}public BigDecimal getPrice(){return price;}public String getCurrency(){return currency;}public Integer getDurationHours(){return durationHours;}public CurriculumMode getCurriculumMode(){return curriculumMode;}public CourseStatus getStatus(){return status;}public User getTeacher(){return teacher;}public String getPrerequisites(){return prerequisites;}public String getLearningOutcomes(){return learningOutcomes;}public String getRejectionReason(){return rejectionReason;}
}
